#!/usr/bin/env python3
from pathlib import Path
from datetime import datetime
import base64
import shutil
import subprocess

PAYLOAD = {
  "lib/tiktokPublisher.js": "",
  "commands/tiktokauth.js": "",
  "commands/tiktokaccount.js": "",
  "commands/tiktokpost.js": "",
  "commands/tiktokconfirm.js": "",
  "commands/tiktokstatus.js": "",
  "commands/tiktokcancel.js": "",
  "commands/tiktoklogout.js": "",
  "TIKTOK-PUBLISHER-SETUP.md": ""
}

INSTALLER_VERSION = "2.2.0"
# Installer-only: dokumentasi .md tidak ditulis ke project.
PAYLOAD.pop("TIKTOK-PUBLISHER-SETUP.md", None)

ENV_BLOCK = """
# TikTok Content Posting API (Direct Post)
# Jangan commit nilai rahasia ke repository.
TIKTOK_CLIENT_KEY=
TIKTOK_CLIENT_SECRET=
TIKTOK_REDIRECT_URI=https://example.com/tiktok/callback
TIKTOK_OAUTH_PORT=8787
TIKTOK_OAUTH_HOST=0.0.0.0
TIKTOK_SCOPES=video.publish
TIKTOK_MAX_VIDEO_MB=512
"""


def fail(message):
    print(f"❌ {message}")
    raise SystemExit(1)


def main():
    print(f'🚀 TikTok Publisher Installer v{INSTALLER_VERSION}')
    root = Path.cwd()
    if not (root / 'package.json').is_file() or not (root / 'commands').is_dir() or not (root / 'lib').is_dir():
        fail('Jalankan installer dari root project wa-bot (folder yang berisi package.json).')

    stamp = datetime.now().strftime('%Y%m%d-%H%M%S')
    backup_root = root / 'backups' / f'tiktok-publisher-{stamp}'
    backup_root.mkdir(parents=True, exist_ok=True)

    for rel, encoded in PAYLOAD.items():
        target = root / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        if target.exists():
            backup = backup_root / rel
            backup.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(target, backup)
        target.write_bytes(base64.b64decode(encoded))
        print(f'✅ write {rel}')

    env_example = root / '.env.example'
    old = env_example.read_text(encoding='utf-8') if env_example.exists() else ''
    if 'TIKTOK_CLIENT_KEY=' not in old:
        env_example.write_text(old.rstrip() + '\n' + ENV_BLOCK, encoding='utf-8')
        print('✅ update .env.example')
    else:
        print('ℹ️ .env.example sudah punya konfigurasi TikTok, tidak ditimpa.')

    print()
    print(f'🔎 Syntax check JS only ({INSTALLER_VERSION})...')
    js_files = [rel for rel in PAYLOAD if rel.endswith('.js')]
    for rel in js_files:
        result = subprocess.run(['node', '--check', str(root / rel)], text=True)
        if result.returncode != 0:
            fail(f'node --check gagal: {rel}')
    print(f'✅ {len(js_files)} file JS lolos syntax check.')

    print()
    print('✅ TikTok publisher terpasang.')
    print(f'📦 Backup file lama: {backup_root}')
    print()
    print('Isi .env dengan credential TikTok Developer:')
    print('  TIKTOK_CLIENT_KEY=...')
    print('  TIKTOK_CLIENT_SECRET=...')
    print('  TIKTOK_REDIRECT_URI=https://domain-kamu/tiktok/callback')
    print('  TIKTOK_OAUTH_PORT=8787')
    print()
    print('Pastikan redirect URI HTTPS tersebut diarahkan/reverse-proxy ke port TIKTOK_OAUTH_PORT.')
    print()
    print('Setelah bot restart:')
    print('  .tiktokauth')
    print('  .tiktokaccount')
    print('  reply video -> .tiktokpost caption')
    print('  lalu ikuti format .tiktokconfirm yang diberikan bot')
    print()
    print('Git:')
    print('  git add .')
    print('  git commit -m "feat: add owner-only TikTok publisher"')
    print('  git push origin main')


if __name__ == '__main__':
    main()
